  // "bi bi-laptop" / "bi-laptop" / "laptop-fill" all have to land on "laptop".
  $key = $name;
  if (str_contains($key, ' ')) {
    foreach (preg_split('/\s+/', $key) as $part) {
      if ($part !== '' && $part !== 'bi' && $part !== 'bs' && $part !== 'bootstrap-icons') {
        $key = $part;
      }
    }
  }
  $key = preg_replace('/^(bi|bs|icon)-/', '', $key);

  $resolve = function ($k) use ($paths, $aliases) {
    if ($k === '') {
      return null;
    }
    if (isset($paths[$k])) {
      return $k;
    }
    if (isset($aliases[$k]) && isset($paths[$aliases[$k]])) {
      return $aliases[$k];
    }
    return null;
  };

  $resolved = $resolve($key);

  if ($resolved === null) {
    // "-fill" / "-square" / trailing digit variants of the same Bootstrap glyph.
    $bare = preg_replace('/-(fill|outline|square|circle|reverse|alt)$/', '', $key);
    $bare = preg_replace('/\d+$/', '', $bare);
    $resolved = $resolve($bare);
  }

  if ($resolved === null) {
    $resolved = $resolve(strtolower(trim((string) $fallback)));
