  $isSolid = $resolved !== null && in_array($resolved, $solid, true);

  // Glyphs that carry a reading direction and so have to mirror under dir=rtl.
  // Circular arrows (refresh, rotate-ccw) and the magnifier keep their shape,
  // which is the usual convention, and brand marks are never mirrored.
  $directional = [
    'arrow-left', 'arrow-right', 'chevron-left', 'chevron-right',
    'log-in', 'log-out', 'send', 'paper-plane', 'external', 'shuffle', 'quote',
  ];
  $isDirectional = $resolved !== null && in_array($resolved, $directional, true);

  // `$attributes->merge` concatenates, and Tailwind emits .w-4 before .w-5, so a
  // default of "w-5 h-5" silently beat every caller that asked for a smaller
  // icon. Only fall back to it when the caller sized nothing itself.
  $callerClass = (string) $attributes->get('class');
  $hasSize = (bool) preg_match('/(^|\s)(w-|h-|size-)/', $callerClass);

  $base = 'store-ico'
    . ($isDirectional ? ' store-ico-flip' : '')
    . ($hasSize ? '' : ' w-5 h-5');
@endphp

@if ($d)
  <svg xmlns="http://www.w3.org/2000/svg"
       viewBox="0 0 24 24"
       fill="{{ $isSolid ? 'currentColor' : 'none' }}"
       stroke="{{ $isSolid ? 'none' : 'currentColor' }}"
       stroke-width="{{ $isSolid ? 0 : $stroke }}"
       stroke-linecap="round"
       stroke-linejoin="round"
       aria-hidden="true"
       focusable="false"
       {{ $attributes->merge(['class' => $base]) }}>
    {!! $d !!}
  </svg>
@endif
